contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address log, uint val) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        bool setLogFileReverted;
        c.SetLogFile(log); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setLogFileReverted = true;
        } else {
            setLogFileReverted = false;
        }

        bool setMinSumReverted;
        c.SetMinSum(val); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setMinSumReverted = true;
        } else {
            setMinSumReverted = false;
        }

        assert(!setLogFileReverted && !setMinSumReverted && c.MinSum() == val);
    }

    receive() external payable {}
}

